package com.progressly.activity.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
@Entity @Table(name="habit_logs",uniqueConstraints=@UniqueConstraint(columnNames={"habitId","userId","logDate"})) public class HabitLog { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(nullable=false) UUID habitId; @Column(nullable=false) UUID userId; @Column(nullable=false) LocalDate logDate; @Column(nullable=false) boolean completed; @Column(precision=19,scale=4) BigDecimal value; @Column(nullable=false) Instant createdAt; protected HabitLog(){} public HabitLog(UUID h,UUID u,LocalDate d,boolean c,BigDecimal v){habitId=h;userId=u;logDate=d;completed=c;value=v;} @PrePersist void create(){createdAt=Instant.now();} public UUID getId(){return id;} public UUID getHabitId(){return habitId;} public LocalDate getLogDate(){return logDate;} public boolean isCompleted(){return completed;} public BigDecimal getValue(){return value;} public void update(boolean c,BigDecimal v){completed=c;value=v;} }
